212	static int qcprobe(struct usb_serial *serial, const struct usb_device_id *id)
213	{
214		struct usb_host_interface *intf = serial->interface->cur_altsetting;
215		struct device *dev = &serial->dev->dev;
216		int retval = -ENODEV;
217		__u8 nintf;
218		__u8 ifnum;
219		int altsetting = -1;
220		bool sendsetup = false;
221	
222		/* we only support vendor specific functions */
223		if (intf->desc.bInterfaceClass != USB_CLASS_VENDOR_SPEC)
224			goto done;
225	
226		nintf = serial->dev->actconfig->desc.bNumInterfaces;
227		dev_dbg(dev, "Num Interfaces = %d\n", nintf);
228		ifnum = intf->desc.bInterfaceNumber;
229		dev_dbg(dev, "This Interface = %d\n", ifnum);
230	
231		if (nintf == 1) {
232			/* QDL mode */
233			/* Gobi 2000 has a single altsetting, older ones have two */
234			if (serial->interface->num_altsetting == 2)
235				intf = &serial->interface->altsetting[1];
236			else if (serial->interface->num_altsetting > 2)
237				goto done;
238	
239			if (intf->desc.bNumEndpoints == 2 &&
240			    usb_endpoint_is_bulk_in(&intf->endpoint[0].desc) &&
241			    usb_endpoint_is_bulk_out(&intf->endpoint[1].desc)) {
242				dev_dbg(dev, "QDL port found\n");
243	
244				if (serial->interface->num_altsetting == 1)
245					retval = 0; /* Success */
246				else
247					altsetting = 1;
248			}
249			goto done;
250	
251		}
252	
253		/* default to enabling interface */
254		altsetting = 0;
255	
256		/*
257		 * Composite mode; don't bind to the QMI/net interface as that
258		 * gets handled by other drivers.
259		 */
260	
261		switch (id->driver_info) {
262		case QCSERIAL_G1K:
